15	     * Returns a 423 deny Response when the actor's account is pending deletion,
16	     * otherwise null. Caller convention: any write-capable ability returns
17	     * this result early when non-null.
18	     */
19	    protected function denyIfPendingDeletion(Professional $professional): ?Response
20	    {
21	        if ($professional->isPendingDeletion()) {
22	            return Response::denyWithStatus(423, 'Account is pending deletion.');
23	        }
24	
25	        return null;
26	    }
27	}
