265	    /**
266	     * Ensure every account-type-allowed section exists and is always enabled.
267	     * Never changes sort_order for existing blocks — only assigns one to new blocks
268	     * (max existing + 1) to avoid conflicts with the partial unique index on
269	     * (site_id, block_group, sort_order) WHERE block_group = 'sections'.
270	     *
271	     * @param  array<int, string>  $allowedSections
272	     */
273	    private function syncAllowedSections(string $professionalId, string $siteId, array $allowedSections): Collection
274	    {
275	        $orderedAllowed = array_values(array_unique(array_filter($allowedSections, static fn ($value) => is_string($value))));
276	
277	        return DB::transaction(function () use ($professionalId, $siteId, $orderedAllowed) {
278	            DB::select('select pg_advisory_xact_lock(hashtext(?))', ["blocks-sections:{$siteId}"]);
279	
280	            // Query ALL section blocks (not just allowed types) so the max sort_order
281	            // calculation accounts for every existing row and new blocks are never
282	            // inserted at a position already held by a non-allowed block.
283	            $allBlocks = Block::query()
284	                ->where('professional_id', $professionalId)
285	                ->where('site_id', $siteId)
286	                ->where('block_group', 'sections')
287	                ->get();
288	
289	            $byType = $allBlocks->keyBy('block_type');
290	            $maxSortOrder = $allBlocks->max('sort_order') ?? -1;
291	
292	            foreach ($orderedAllowed as $blockType) {
293	                $block = $byType->get($blockType) ?? new Block([
294	                    'professional_id' => $professionalId,
295	                    'site_id' => $siteId,
296	                    'block_group' => 'sections',
297	                    'block_type' => $blockType,
298	                ]);
299	
300	                if (! $block->exists) {
301	                    $block->settings = [];
302	                    $block->is_active = false;
303	                    $block->sort_order = ++$maxSortOrder;
304	                }
305	
306	                $block->is_enabled = true;
307	                $block->save();
308	                $byType->put($blockType, $block);
309	            }
310	
311	            return $byType->values();
312	        });
313	    }
