321	
322	        // Expose the visibility gate state to the frontend so the Publish
323	        // button can disable + show its tooltip reason without duplicating
324	        // the rule set. Only queried when the ids are provided (the index
325	        // action supplies them; upsert/remove reuse this serializer post-
326	        // mutation and can skip the check since they already enforced it).
327	        if ($professionalId !== null && $siteId !== null) {
