5	use App\Models\Core\Professional\Professional;
6	use Illuminate\Auth\Access\Response;
7	
8	// V2: Base for all auth Policies. Provides the shared pending_deletion read-only
9	// guard. Concrete Policies call denyIfPendingDeletion() as the first line of any
10	// ability that mutates state — this mirrors the EnforcePendingDeletionReadOnly
11	// HTTP middleware so background jobs and console commands get the same gate.
12	abstract class BasePolicy
13	{
14	    /**
15	     * Returns a 423 deny Response when the actor's account is pending deletion,
16	     * otherwise null. Caller convention: any write-capable ability returns
17	     * this result early when non-null.
18	     */
19	    protected function denyIfPendingDeletion(Professional $professional): ?Response
20	    {
21	        if ($professional->isPendingDeletion()) {
22	            return Response::denyWithStatus(423, 'Account is pending deletion.');
23	        }
24	
25	        return null;
26	    }
27	}
