5	use App\Models\Core\Professional\Professional;
6	use App\Models\Core\Professional\ProfessionalIntegration;
7	use App\Services\Store\BrandAccessService;
8	use Illuminate\Auth\Access\Response;
9	
10	// V2: Authorization for ProfessionalIntegration (Square / Fresha / Shopify
11	// OAuth credentials). Two abilities:
12	//
13	//   view   — actor owns the integration OR has brand-team manage capability
14	//            for the integration's owning professional.
15	//   manage — same as view, plus the actor must not be pending_deletion
16	//            (returns 423 via BasePolicy::denyIfPendingDeletion).
17	//
18	// We use a single 'manage' ability covering connect/disconnect/sync because
19	// BrandAccessService already buckets these into CAPABILITY_SHOPIFY_MANAGE.
20	// Split if a role ever needs "sync but not disconnect".
21	class IntegrationPolicy extends BasePolicy
22	{
23	    public function __construct(private readonly BrandAccessService $brandAccess) {}
24	
25	    public function view(Professional $actor, ProfessionalIntegration $integration): bool
26	    {
27	        return $this->actorCanReachOwner($actor, $integration);
28	    }
29	
30	    public function manage(Professional $actor, ProfessionalIntegration $integration): bool|Response
31	    {
32	        if ($denied = $this->denyIfPendingDeletion($actor)) {
33	            return $denied;
34	        }
35	
36	        return $this->actorCanReachOwner($actor, $integration);
37	    }
38	
39	    private function actorCanReachOwner(Professional $actor, ProfessionalIntegration $integration): bool
40	    {
41	        $ownerId = trim((string) ($integration->professional_id ?? ''));
42	        if ($ownerId === '') {
43	            return false;
44	        }
45	
46	        if ((string) $actor->id === $ownerId) {
47	            return true;
48	        }
49	
50	        return $this->brandAccess->canManageShopify($actor, $ownerId);
51	    }
52	}
